package com.bank.flatten.service;

import com.bank.flatten.model.Department;
import com.bank.flatten.model.Employee;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class OrgFlattenService {
    private static final Logger log = Logger.getLogger(OrgFlattenService.class.getName());

    public List<Employee> allEmployees(List<Department> departments) {
        log.info(() -> "Flattening employees across " + departments.size() + " departments");
        return departments.stream()
                // Each department's list → a stream; flatMap concatenates them all.
                .flatMap(d -> d.getEmployees().stream())
                .collect(Collectors.toList());
    }
}
