package com.bank.flatten;

import com.bank.flatten.model.Department;
import com.bank.flatten.model.Employee;
import com.bank.flatten.service.OrgFlattenService;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        Department it    = new Department("IT",    List.of(new Employee("Rajesh"), new Employee("Neha")));
        Department sales = new Department("Sales", List.of(new Employee("Priya")));
        Department ops   = new Department("Ops",   List.of());  // empty → disappears

        List<Employee> all = new OrgFlattenService().allEmployees(List.of(it, sales, ops));
        log.info(() -> "All employees (flat): " + all);
    }
}
